//! Basic 64-bit integer geometry types and helpers.
//!
//! Re-implements the small subset of Clipper2's geometry utilities used by
//! this program: the `Point64`/`Path64`/`Paths64` types, the signed polygon
//! area, path translation, and the winding-number query.

/// A point with 64-bit integer coordinates.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    /// Creates a new point from its coordinates.
    pub fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }
}

/// A polygon contour: an ordered list of vertices.
pub type Path64 = Vec<Point64>;

/// A collection of polygon contours.
pub type Paths64 = Vec<Path64>;

/// Signed area of a polygon via the shoelace formula.
///
/// Positive for counter-clockwise winding, negative for clockwise winding,
/// matching Clipper2's `Area()`. The computation is done in `f64`, exactly
/// as Clipper2 does.
pub fn area(path: &Path64) -> f64 {
    let n = path.len();
    if n < 3 {
        return 0.0;
    }
    let mut sum = 0.0;
    let mut prev = path[n - 1];
    for &curr in path.iter() {
        sum += (prev.x as f64) * (curr.y as f64) - (curr.x as f64) * (prev.y as f64);
        prev = curr;
    }
    sum * 0.5
}

/// Returns a copy of all paths translated by `(dx, dy)`,
/// matching Clipper2's `TranslatePaths()`.
pub fn translate_paths(paths: &Paths64, dx: i64, dy: i64) -> Paths64 {
    paths
        .iter()
        .map(|path| {
            path.iter()
                .map(|pt| Point64::new(pt.x + dx, pt.y + dy))
                .collect()
        })
        .collect()
}

/// Winding number of the point `(px, py)` with respect to `path`.
///
/// Counts how many times the polygon winds around the point using the
/// standard upward/downward ray-crossing algorithm: edges crossing the
/// horizontal ray to the right of the point contribute +1 when directed
/// upward and -1 when directed downward. The point is assumed to lie
/// strictly off the polygon boundary.
pub fn winding_number(path: &Path64, px: f64, py: f64) -> i32 {
    let n = path.len();
    if n < 3 {
        return 0;
    }
    let mut winding: i32 = 0;
    let mut prev = path[n - 1];
    for &curr in path.iter() {
        let prev_y = prev.y as f64;
        let curr_y = curr.y as f64;
        // Consider only edges straddling the horizontal line y = py,
        // using a half-open interval so each crossing is counted once.
        if (prev_y <= py) != (curr_y <= py) {
            // X coordinate where the edge crosses y = py.
            let cross_x = (prev.x as f64)
                + (py - prev_y) / (curr_y - prev_y) * ((curr.x - prev.x) as f64);
            if cross_x > px {
                if curr_y > prev_y {
                    winding += 1; // upward crossing
                } else {
                    winding -= 1; // downward crossing
                }
            }
        }
        prev = curr;
    }
    winding
}

