//! Formatting of `f64` values matching C++ `std::cout << value` with default
//! settings (`std::defaultfloat`, precision 6 — i.e. `printf("%g", v)`).

/// Number of significant digits used by C++ streams by default.
const PRECISION: usize = 6;

/// Format an f64 exactly like C++ `std::cout << value` does by default:
/// 6 significant digits, trailing zeros removed, fixed notation unless the
/// decimal exponent is < -4 or >= 6 (then scientific, e.g. `1.23457e+06`,
/// `1e-05`, with a signed exponent of at least two digits).
pub fn format_double(v: f64) -> String {
    if v.is_nan() {
        return "nan".to_string();
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf" } else { "inf" }.to_string();
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0" } else { "0" }.to_string();
    }

    let negative = v.is_sign_negative();
    let abs = v.abs();

    // Round to PRECISION significant digits by going through scientific
    // notation, e.g. "1.23457e6". Rounding here can bump the decimal
    // exponent (999999.9 -> "1.00000e6"), which is exactly what %g does.
    let sci = format!("{:.*e}", PRECISION - 1, abs);
    let epos = sci.find('e').expect("scientific notation always contains 'e'");
    let digits: String = sci[..epos].chars().filter(|c| *c != '.').collect();
    let exp: i32 = sci[epos + 1..].parse().expect("exponent is an integer");
    debug_assert_eq!(digits.len(), PRECISION);

    let mut out = String::new();
    if negative {
        out.push('-');
    }

    if exp < -4 || exp >= PRECISION as i32 {
        // Scientific notation: d[.ddd]e±XX, trailing zeros of the
        // mantissa removed, exponent signed and at least two digits.
        let mantissa = digits.trim_end_matches('0');
        out.push_str(&mantissa[..1]);
        if mantissa.len() > 1 {
            out.push('.');
            out.push_str(&mantissa[1..]);
        }
        // {:+03} yields e.g. "+06" or "-05" (sign, zero-padded to 2 digits).
        out.push_str(&format!("e{:+03}", exp));
    } else if exp >= 0 {
        // Fixed notation with the decimal point inside (or right after)
        // the significant digits: ddd[.ddd].
        let int_len = exp as usize + 1;
        out.push_str(&digits[..int_len]);
        let frac = digits[int_len..].trim_end_matches('0');
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
    } else {
        // Fixed notation below 1: 0.000ddd (exponent in -4..=-1).
        out.push_str("0.");
        for _ in 0..(-exp - 1) {
            out.push('0');
        }
        out.push_str(digits.trim_end_matches('0'));
    }

    out
}

