mod cppfmt;
use cppfmt::format_double;
fn main() {
    let cases: &[(f64, &str)] = &[
        (6250.0, "6250"),
        (0.1, "0.1"),
        (1.0 / 3.0, "0.333333"),
        (1234567.0, "1.23457e+06"),
        (0.000012345, "1.2345e-05"),
        (100000.0, "100000"),
        (1000000.0, "1e+06"),
        (0.0, "0"),
        (-0.0, "-0"),
        (f64::INFINITY, "inf"),
        (f64::NEG_INFINITY, "-inf"),
        (f64::NAN, "nan"),
        (-6250.5, "-6250.5"),
        (123.456, "123.456"),
        (999999.9, "1e+06"),
        (0.0001, "0.0001"),
        (0.00001, "1e-05"),
        (1.5, "1.5"),
        (123456789.0, "1.23457e+08"),
        (-0.000123456, "-0.000123456"),
        (2.0, "2"),
        (1e-4, "0.0001"),
        (9.999995, "10"),
        (10.0, "10"),
    ];
    let mut fail = 0;
    for (v, want) in cases {
        let got = format_double(*v);
        if got != *want {
            println!("FAIL: {:?} -> {:?}, want {:?}", v, got, want);
            fail += 1;
        }
    }
    if fail == 0 { println!("all {} cases passed", cases.len()); } else { std::process::exit(1); }
}
