//! Stub geom for syntax/behavior checking only.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Point64 { pub x: i64, pub y: i64 }
impl Point64 { pub fn new(x: i64, y: i64) -> Self { Point64 { x, y } } }
